@Composable
fun AddMedicationDialog(
    onDismiss: () -> Unit,
    onSubmit: (name: String, defaultDose: String, minIntervalMinutes: Int?) -> Unit,
) {
    var name by remember { mutableStateOf("") }
    var defaultDose by remember { mutableStateOf("") }
    var intervalHours by remember { mutableStateOf(0) }
    var intervalMinutes by remember { mutableStateOf(0) }

    AlertDialog(
        onDismissRequest = onDismiss,
        title = { Text(stringResource(R.string.add_a_medication)) },
        text = {
            Column {
                OutlinedTextField(
                    value = name,
                    onValueChange = { name = it },
                    label = { Text(stringResource(R.string.name_label)) },
                    modifier = Modifier.fillMaxWidth(),
                )
                OutlinedTextField(
                    value = defaultDose,
                    onValueChange = { defaultDose = it },
                    label = { Text(stringResource(R.string.default_dose_label)) },
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(top = 8.dp),
                )
                Text(
                    stringResource(R.string.min_interval_label),
                    style = MaterialTheme.typography.labelLarge,
                    modifier = Modifier.padding(top = 16.dp),
                )
                DurationPicker(
                    hours = intervalHours,
                    minutes = intervalMinutes,
                    onHoursChange = { intervalHours = it },
                    onMinutesChange = { intervalMinutes = it },
                    modifier = Modifier.padding(top = 4.dp),
                )
            }
        },
        confirmButton = {
            TextButton(
                onClick = {
                    if (name.isNotBlank() && defaultDose.isNotBlank()) {
                        val minIntervalMinutes = (intervalHours * 60 + intervalMinutes).takeIf { it > 0 }
                        onSubmit(name, defaultDose, minIntervalMinutes)
                    }
                },
            ) {
                Text(stringResource(R.string.add))
            }
        },
        dismissButton = {
            TextButton(onClick = onDismiss) { Text(stringResource(R.string.cancel)) }
        },
    )
}
